"""Source-bound visual sections for the project report. No quantum calculations."""
import base64,csv,html,json
from pathlib import Path
from rdkit import Chem
from rdkit.Chem.Draw import rdMolDraw2D
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
REG=ROOT/'results/candidates/pool/2026-11-03_qualified_phenothiazine_context/registry.json'
CAP=ROOT/'manuscript/evidence/2026-11-03_six_chloride_contacts/pmdi_capacity.json'
INPUTS=[HERE/'enrich.py',HERE/'visuals.js',HERE/'visuals.css',HERE/'data/historical_pareto.csv',HERE/'data/historical_scorecard.csv',REG,CAP,ROOT/'results/pareto_shortlist.csv',ROOT/'results/scorecard.csv']

def visuals():
 registry=json.loads(REG.read_text())['candidates']
 cards=[]
 specs=[('viologen','Two-electron negative-side lead','−0.608 / −1.208 V','Two checked electron-accepting steps and favorable local attachment energy (−11.49 kJ/mol).','Finish exact-model transfer-speed checks and occupied-polymer sampling; measure accessible charge and lifetime.'),('phenothiazine','Positive-side lead','+0.626 V','A checked electron-removal step and reviewed attachment precedent. It serves a different electrode role from viologen.','Establish accessible capacity, transfer behavior and durability for the exact graft; a voltage alone is not a full property assessment.'),('tempo','Comparison candidate','Route supported','Reviewed attachment evidence makes this a useful comparison case; its current electron-transfer assessment remains incomplete.','Resolve the unequal forward/reverse rearrangement costs before using one symmetric transfer parameter.')]
 for alias,role,value,why,next_step in specs:
  c=next(c for c in registry if alias in c['aliases'])
  assert c['route_status']=='proceed'
  m=Chem.MolFromSmiles(c['product_smiles']);assert m is not None
  # Identify the benzyl attachment bond from an exact substructure, not atom order.
  query=Chem.MolFromSmarts('c-[CH2]-[N,O,n+]')
  matches=m.GetSubstructMatches(query);assert len(matches)==1,(alias,matches)
  _,benzyl,attachment=matches[0];bond=m.GetBondBetweenAtoms(benzyl,attachment).GetIdx()
  draw=rdMolDraw2D.MolDraw2DSVG(420,230)
  draw.DrawMolecule(m,highlightAtoms=[benzyl,attachment],highlightBonds=[bond]);draw.FinishDrawing()
  svg=draw.GetDrawingText();uri='data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()
  label = 'TEMPO' if alias == 'tempo' else alias.capitalize()
  cards.append(f'<article class="candidate-card"><span class="tag">{role}</span><h3>{label}</h3><img class="molecule" src="{uri}" alt="Exact {alias} local graft; attachment bond highlighted"><div class="candidate-number">{value}</div><p>{why}</p><p class="small"><b>Next evidence:</b> {next_step}</p><details><summary>Exact molecular identity</summary><p class="small">{html.escape(c["inchikey"])}</p><p class="small">{html.escape(c["product_smiles"])}</p></details></article>')
 (ROOT/'results/report/shortlist.json').write_text(json.dumps({
  'status':'evidence_based_followup_priorities_not_validated_material_ranking',
  'current_primary_front_members':0,
  'candidates':[{'id':a,'role':role,'checked_result_summary':v,'reason':why,'missing_evidence':step} for a,role,v,why,step in specs],
  'conditional_property_lead':{'id':'d3_05stji','name':'2-(benzylamino)-1,4-naphthoquinone','status':'historical_only_route_and_QC_review_required','historical_LiPF6_capacity_mAh_g':176.8,'historical_mean_reduction_V':-1.413},
  'capacity_design_case':{'id':'design_pmdi_ethyl','full_five_site_2e_bound_mAh_g':148.58,'mass_scope':'dry neutral H-capped fragment; residual chloride retained; extra inactive mass excluded'},
  'sources':['results/candidates/pool/2026-11-03_qualified_phenothiazine_context/registry.json','scripts/report/data/historical_scorecard.csv','scripts/report/data/historical_pareto.csv','results/scorecard.csv','results/pareto_shortlist.csv']
 },indent=2)+'\n')
 historical=list(csv.DictReader((HERE/'data/historical_pareto.csv').open()))
 current=list(csv.DictReader((ROOT/'results/pareto_shortlist.csv').open()))
 count=sum(r['pareto_optimal']=='True' for r in current)
 assert count==0,'Current shortlist changed; review narrative before rebuilding'
 cap=json.loads(CAP.read_text())
 payload=json.dumps({'historical':historical,'capacity':cap['composition_grid']},ensure_ascii=False).replace('</','<\\/')
 shortlist='''<section id="shortlist"><div class="section-head"><div class="eyebrow">Decision guide / Candidates to take forward</div><h2>Three candidates to take forward.</h2><p>Start with route-supported designs and complete their missing properties. Compare electron-accepting and electron-donating candidates separately; they serve different sides of a battery. These priorities reflect available evidence, not a weighted performance score. <a href="#source-4">[4]</a></p></div><div class="candidate-grid">'''+''.join(cards)+'''</div><p class="small">Exact registered local-site structures. The highlighted bond joins the redox group to the benzyl site. These capped molecules are not full polymer structures; the drawing does not establish where charge or spin resides.</p><div class="note"><b>Conditional property lead: 2-(benzylamino)-1,4-naphthoquinone (d3_05stji).</b> The archived screen reported 176.8 mAh/g in its LiPF₆ mass scenario and an average reduction potential of −1.413 V. But its electron-transfer quality check is partial, its thermal record has imaginary modes, and the archived route note questions direct N-benzylation onto this support (<a href="../../scripts/report/data/historical_scorecard.csv">source record</a>). Keep it as a property target for route and calculation review, not a synthesis-ready recommendation.</div><p><b>PMDI is a capacity-design case.</b> Its loading-dependent bounds below are informative, but they do not establish accessible two-electron capacity in the polymer or a material-level win.</p></section>'''
 pareto='''<section id="pareto"><div class="section-head"><div class="eyebrow">Compare trade-offs / Pareto front</div><h2>Which candidates avoid being beaten on every property?</h2><p>A Pareto front contains candidates for which no alternative is at least as good on every chosen property and better on at least one, allowing for the pipeline’s uncertainty rules. Here those properties are voltage, stored charge per gram, resistance to one electron-exchange reaction, and rearrangement energy.</p></div><div class="takeaway"><b>Current qualified front: no members.</b> The current scorecard has an incomplete mophquinone entry and a phthalimide control with a flagged rearrangement calculation. Its two salt-scenario shortlist rows are both incomplete. The recently checked molecular cases above are not complete multi-property scorecards. An empty front is missing evidence—not proof that the candidates are poor.</div><div class="panel"><span class="tag warn">Archived exploratory comparison · not current qualification</span><h3 style="margin-top:15px">Earlier candidates show the trade-offs worth revisiting.</h3><p class="small">This plot projects the archived four-property analysis onto voltage and capacity. Stars reproduce the front flags in that archive; they are not a newly validated two-property front. Several old entries admitted partial electron-transfer checks, so their historical ranking must not be promoted under today’s rules.</p><div class="controls" role="group" aria-label="Historical capacity scenario"><button data-salt="LiPF6" aria-pressed="true">LiPF₆ mass scenario</button><button data-salt="TBAPF6" aria-pressed="false">TBAPF₆ mass scenario</button></div><div id="pareto-plot" class="plot-scroll"></div><p class="small">★ Archived front flag · ○ Other archived entries. Farther right: more negative average reduction potential, which can increase cell voltage with a fixed positive-side partner if both steps remain usable. Higher: more nominal charge per gram. No line joins the stars because this is only a two-axis view.</p><p id="pareto-summary" aria-live="polite"></p><details><summary>Read the plotted values and calculation flags</summary><div id="pareto-table" class="table-wrap"></div></details></div><p class="small">Source: <a href="../../scripts/report/data/historical_pareto.csv">frozen archived shortlist</a>; original at <code>~/archive/0_redox/results/pareto_shortlist.csv</code>. Current status: <a href="../pareto_shortlist.csv">current shortlist</a> and <a href="../scorecard.csv">scorecard</a>. Archived potentials and capacities are not substituted for the newer exact-model results above.</p></section>'''
 capacity='''<div class="panel" id="capacity-explorer"><span class="tag">Explore a declared composition</span><h3 style="margin-top:15px">Build a five-repeat PMDI segment</h3><div class="capacity-controls"><label>Attachment handles <select id="handle-count">'''+''.join(f'<option value="{i}" {"selected" if i==3 else ""}>{i} of 5</option>' for i in range(6))+'''</select></label><label>Occupied handles <select id="graft-count"></select></label><label>Electrons per graft <select id="electron-count"><option value="1">1</option><option value="2" selected>2 assumed</option></select></label></div><div id="capacity-chain"></div><div class="grid"><div><div class="metric" id="capacity-value"></div><p>Nominal upper bound in mAh/g</p></div><div><p id="capacity-composition"></p><p id="capacity-mass" class="small"></p></div></div><p class="small">Green: PMDI graft · amber: unused benzyl-chloride handle · gray: styrene without a handle. The order shown is an illustration, not a predicted sequence or shape. The chain continues between its ends; dots are repeat-unit symbols, not atoms.</p><div class="note">Mass basis: dry, neutral, hydrogen-capped five-repeat fragment; unused chloride is retained. No extra electrolyte, crosslinker or other inactive mass is included. Full use of the selected electron budget is assumed. Counterion-containing scenarios require their own mass treatment. This is not a forecast of measured capacity.</div><p class="small">Exact-graph source: <a href="../../manuscript/evidence/2026-11-03_six_chloride_contacts/pmdi_capacity.json">PMDI composition grid</a>. At five handles and five grafts, the two-electron bound is <b>148.58 mAh/g</b>; three handles fully occupied give <b>124.52 mAh/g</b>. Added mass or inaccessible sites reduces these ceilings.</p></div>'''
 return {'shortlist':shortlist,'pareto':pareto,'capacity_explorer':capacity,'visual_data':'<script id="visual-data" type="application/json">'+payload+'</script>','visual_js':'<script>'+(HERE/'visuals.js').read_text()+'</script>','visual_css':'<style>'+(HERE/'visuals.css').read_text()+'</style>'}
